// src/dashboard.config.ts: the project's choices for sign-in and the dashboard.
import type { AuthMethod, DashboardConfig, DashboardModuleName, OAuthProviderName } from '@cossackframework/dashboard';

const methods: AuthMethod[] = ['credentials', 'oauth'];
const providers: OAuthProviderName[] = ['github', 'google'];
const modules: DashboardModuleName[] = ['users', 'sessions', 'settings'];

export const dashboard: DashboardConfig = {
    authMethods: methods,
    oauth: providers,
    // The roles pages answer 404: the module is not listed.
    modules,
    redirectAfterLogin: '/dashboard',
};
